import datetime,hashlib,json,os,stat,subprocess,sys,time
from pathlib import Path
ROOT=Path('/workspace/android-studio-reference-membership')
EVIDENCE=Path('/workspace/android-studio-artifacts/reference-runner-membership/runtime')
SOURCE=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
PATHS=['.',':(glob,exclude)docs/android-studio/*.md',':(exclude)docs/android-studio/reference-manifest.json',':(exclude)docs/android-studio/test-parity.json',':(glob,exclude)docs/android-studio/ports/*.json',':(glob,exclude)docs/android-studio/evidence/**/*.log',':(glob,exclude)docs/android-studio/evidence/**/*.json']
def git(*args): return subprocess.check_output(['git',*args],cwd=ROOT)
def snapshot():
 names=git('ls-files','-z','--',*PATHS).decode().split('\0')[:-1]
 files={}
 for name in names:
  path=ROOT/name; mode=path.lstat().st_mode
  if stat.S_ISLNK(mode): data=os.readlink(path).encode()
  else:
   assert stat.S_ISREG(mode), name
   data=path.read_bytes()
  files[name]={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'mode':mode}
 return {'source_commit':git('rev-parse','HEAD').decode().strip(),'source_pathspecs':PATHS,'source_file_count':len(names),'files':files,'index_hex':git('ls-files','--stage','-z').hex(),'status_hex':git('status','--porcelain=v1','-z','--untracked-files=all').hex(),'diff':git('diff','--binary').hex(),'cached_diff':git('diff','--cached','--binary').hex()}
EVIDENCE.mkdir(exist_ok=True)
stage=sys.argv[1];command=sys.argv[2:];assert command
before=snapshot();assert before['source_commit']==SOURCE and before['status_hex']==''
start=time.monotonic();started=datetime.datetime.now(datetime.timezone.utc).isoformat();free_before={p:os.statvfs(p).f_bavail*os.statvfs(p).f_frsize for p in ['/workspace','/tmp']}
log=EVIDENCE/(stage+'.log');receipt=EVIDENCE/(stage+'.json');assert not log.exists() and not receipt.exists()
(EVIDENCE/(stage+'-whole-source-before.json')).write_text(json.dumps(before,sort_keys=True,indent=2)+'\n')
with log.open('xb') as output:
 process=subprocess.run(command,cwd=ROOT,stdout=output,stderr=subprocess.STDOUT)
after=snapshot();same=before==after
result={'schema_version':1,'stage':stage,'source_commit':SOURCE,'started_at_utc':started,'duration_seconds':time.monotonic()-start,'command':command,'exit_code':process.returncode,'raw_log':str(log),'raw_log_bytes':log.stat().st_size,'raw_log_sha256':hashlib.sha256(log.read_bytes()).hexdigest(),'full_source_index_status_unchanged':same,'source_file_count':before['source_file_count'],'before_snapshot':str(EVIDENCE/(stage+'-whole-source-before.json')),'free_bytes_before':free_before,'free_bytes_after':{p:os.statvfs(p).f_bavail*os.statvfs(p).f_frsize for p in ['/workspace','/tmp']},'compiler_executed':command[:2] in [['cargo','test'],['cargo','build']] or command[0]=='./script/clippy','original_behavior_credit':0,'runtime_cases':None,'global_census_complete':False}
receipt.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2),flush=True)
assert same,'Source/index/status changed during gate'
sys.exit(process.returncode)
